PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS return_requests (id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),order_id TEXT NOT NULL REFERENCES orders(id),customer_id TEXT NOT NULL REFERENCES customers(id),status TEXT NOT NULL CHECK (status IN ('REQUESTED','APPROVED','RECEIVED','COMPLETED','CANCELLED')),reason TEXT NOT NULL,return_reference TEXT NOT NULL,correlation_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS uq_return_requests_tenant_order ON return_requests(tenant_id,order_id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_return_requests_tenant_reference ON return_requests(tenant_id,return_reference);
CREATE INDEX IF NOT EXISTS idx_return_requests_tenant_status ON return_requests(tenant_id,status);
CREATE TABLE IF NOT EXISTS return_events (id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),return_request_id TEXT NOT NULL REFERENCES return_requests(id) ON DELETE CASCADE,order_id TEXT NOT NULL REFERENCES orders(id),from_status TEXT,to_status TEXT NOT NULL CHECK (to_status IN ('REQUESTED','APPROVED','RECEIVED','COMPLETED','CANCELLED')),correlation_id TEXT NOT NULL,idempotency_key TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_return_events_time ON return_events(return_request_id,created_at);
CREATE TABLE IF NOT EXISTS refund_requests (id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),order_id TEXT NOT NULL REFERENCES orders(id),payment_intent_id TEXT NOT NULL REFERENCES payment_intents(id),amount REAL NOT NULL CHECK (amount > 0),currency TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('REQUESTED','APPROVED','PROCESSING','COMPLETED','FAILED','CANCELLED')),reason TEXT NOT NULL,refund_reference TEXT NOT NULL,correlation_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS uq_refund_requests_tenant_payment ON refund_requests(tenant_id,payment_intent_id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_refund_requests_tenant_reference ON refund_requests(tenant_id,refund_reference);
CREATE INDEX IF NOT EXISTS idx_refund_requests_tenant_status ON refund_requests(tenant_id,status);
CREATE TABLE IF NOT EXISTS refund_events (id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),refund_request_id TEXT NOT NULL REFERENCES refund_requests(id) ON DELETE CASCADE,order_id TEXT NOT NULL REFERENCES orders(id),payment_intent_id TEXT NOT NULL REFERENCES payment_intents(id),from_status TEXT,to_status TEXT NOT NULL CHECK (to_status IN ('REQUESTED','APPROVED','PROCESSING','COMPLETED','FAILED','CANCELLED')),correlation_id TEXT NOT NULL,idempotency_key TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_refund_events_time ON refund_events(refund_request_id,created_at);
